import{_ as s}from"./plugin-vue_export-helper-c27b6911.js";import{o as a,c as n,a as e}from"./app-7f129259.js";const t={},o=e(`<h1 id="oroklodes" tabindex="-1"><a class="header-anchor" href="#oroklodes" aria-hidden="true">#</a> Öröklődés</h1><div class="hint-container note"><p class="hint-container-title">Röviden</p><ul><li>Az öröklés lehetővé teszi, hogy új osztályokat származtassunk a meglévők osztályokból.</li><li>Az új osztály a konstruktorok kivételével mindent az ősosztályból örököl.</li><li>Az osztályok alapértelmezés szerint az <code>object</code>-ből származtatnak.</li><li>A <code>protected</code> hozzáférési módosító lehetővé teszi a dolgok elérését az osztályban és minden származtatott osztályban.</li></ul></div><p>Az objektumorientált programozásban gyakran előfordul, hogy egy osztály egy másik osztály leszármazottja, amelyeket a leszármaztatott osztály tovább bővít vagy fejleszt. Lássunk egy példát a való életből, amely bemutatja ezt a típusú öröklődési viszonyt:</p><ul><li>Az <strong>íróeszközök</strong> lehetővé teszik szöveg írását vagy képek rajzolását papírra. <ul><li><em>A</em> <strong>ceruzák</strong> <em>ezt azzal egészítik ki, hogy lehetőséget adnak a radírozásra.</em></li><li><em>A</em> <strong>színes ceruzák</strong> <em>színt adnak.</em></li><li><em>A</em> <strong>tollak</strong> <em>a tinta szintjének és a tinta kifogyásának fogalmát hozzák létre.</em></li></ul></li></ul><p><strong>Viszont mindegyiket használhatjuk írásra és rajzolásra.</strong></p><p>Ezt az altípusú kapcsolatot C# kódban az öröklés segítségével definiálhatjuk. Lehetővé teszi, hogy az altípusokat úgy kezeljük, mint a megkettőzött vagy másolt kódot két szorosan kapcsolódó osztályban. Ez a kapcsolat gyakori az objektumorientált programozásban. Az olyan kapcsolatot, amelyben egy típus egy másikra kiterjeszthető, öröklési kapcsolatnak nevezzük. Az <strong>öröklődés</strong> az objektumorientált programozás negyedik legfontosabb alapelve:</p><div class="hint-container tip"><p class="hint-container-title">Objektumorientált elv #4</p><p><strong>Öröklődés</strong> - Egy osztály egy másikra épül, megtartva az eredeti osztály funkcionalitását, miközben az új osztályt további képességekkel bővíti.</p></div><h2 id="oroklodes-es-az-object-osztaly" tabindex="-1"><a class="header-anchor" href="#oroklodes-es-az-object-osztaly" aria-hidden="true">#</a> Öröklödés és az <code>object</code> osztály</h2><p>Amikor két osztály között öröklési kapcsolatot definiálunk, három dolog történik:</p><ul><li>Az új osztály megkap mindent, amivel a régi osztály rendelkezet.</li><li>Az új osztály hozzáadhat extra dolgokat.</li><li>Az új osztályt úgy lehet kezelni, mint az eredetit, hiszen rendelkezik minden szükséges képességgel.</li></ul><p>Az eredeti osztály, amelyre építünk, az <strong>alaposztály</strong>, bár néha <strong>szülőosztálynak</strong> vagy <strong>szuperosztálynak</strong> is nevezik. Az új osztály, amely kiterjeszti az alaposztályt, a <strong>leszármazott</strong> osztály, bár néha <strong>gyermekosztálynak</strong> vagy <strong>alosztálynak</strong> is hívják.</p><div class="hint-container note"><p class="hint-container-title">A programozók nem mindig használnak következetes terminológiát.</p></div><p>Azt mondják, hogy a leszármazott osztály származik az alaposztályból, vagy hogy a leszármazott osztály kiterjeszti az alaposztályt. Tegyük ezt világosabbá egy konkrét példával. Mint kiderült, már egy ideje tudtunk nélkül használjuk az öröklődést. Minden általunk definiált osztály automatikusan rendelkezik egy alaposztállyal, amelynek neve <code>object</code>. Amikor létrehoztunk egy <code>Asteroid</code> vagy egy <code>Point</code> osztályt, ezek az <code>object</code> osztályból származtak vagy azt kiterjesztették. Az <code>Asteroid</code> és a <code>Point</code> ebben a kapcsolatban a <strong>leszármazott</strong> osztályok és az <code>object</code> az <strong>alaposztály</strong>.</p><p>Az <code>object</code> osztály különleges. Ez azt jelenti, hogy bármi, amit az objektumosztály definiál, minden egyes valaha létrehozott objektumon létezik. Nézzük meg az objektumosztályt és vessünk egy pillantást az öröklődés működésére:</p><div class="language-csharp line-numbers-mode" data-ext="cs"><pre class="language-csharp"><code><span class="token class-name"><span class="token keyword">object</span></span> thing <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token constructor-invocation class-name"><span class="token keyword">object</span></span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>Az object osztály nem sok feladattal rendelkezik, ezért az <code>object</code> példányainak létrehozása viszonylag ritka. Több metódusa van, de most kettőt vizsgálunk meg: a <code>ToString</code> és az <code>Equals</code>. A <code>ToString</code> metódus egy objektum szöveges reprezentációját hozza létre. Az alapértelmezett megvalósítás az objektum típusának teljes nevének megjelenítése.</p><div class="language-csharp line-numbers-mode" data-ext="cs"><pre class="language-csharp"><code>Console<span class="token punctuation">.</span><span class="token function">WriteLine</span><span class="token punctuation">(</span>thing<span class="token punctuation">.</span><span class="token function">ToString</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>A kód a következőt fogja megjeleníteni: <strong>System.Object</strong>, mivel az <code>Object</code> osztály a <code>System</code> névtérben található.<br> Az <code>Equals</code> metódus egy <strong>bool</strong> értéket ad vissza, amely jelzi, hogy két dolog egyenlőnek tekinthető-e vagy sem.</p><p>A következő kód <code>True</code>-t, majd <code>False</code>-t fog megjeleníteni.</p><div class="language-csharp line-numbers-mode" data-ext="cs"><pre class="language-csharp"><code><span class="token class-name"><span class="token keyword">object</span></span> a <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token constructor-invocation class-name"><span class="token keyword">object</span></span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token class-name"><span class="token keyword">object</span></span> b <span class="token operator">=</span> a<span class="token punctuation">;</span>
<span class="token class-name"><span class="token keyword">object</span></span> c <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token constructor-invocation class-name"><span class="token keyword">object</span></span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
Console<span class="token punctuation">.</span><span class="token function">WriteLine</span><span class="token punctuation">(</span>a<span class="token punctuation">.</span><span class="token function">Equals</span><span class="token punctuation">(</span>b<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
Console<span class="token punctuation">.</span><span class="token function">WriteLine</span><span class="token punctuation">(</span>a<span class="token punctuation">.</span><span class="token function">Equals</span><span class="token punctuation">(</span>c<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Alapértelmezés szerint az <code>Equals</code> azt adja vissza, hogy két dolog ugyanarra az objektumra hivatkozik-e. Azonban az egyenlőség összetett téma a programozásban.</p><ul><li>Két dolog csak akkor legyen egyenlő, ha ugyanazt a memóriahelyet képviselik?</li><li>Egyenlők legyenek, ha ugyanolyan típusúak és a mezőik egyenlőek?</li><li>Vannak olyan mezők, amelyek számítanak, míg mások nem?</li></ul><p>Különböző körülmények között mindegyik igaz lehet.</p><p>Az osztályok néha újra definiálhatnak egy-egy metódust, beleértve a <code>ToString</code> és az <code>Equals</code> metódusokat is.<br> Mivel az <code>object</code> definiálja a <code>ToString</code> és <code>Equals</code> metódusokat és mivel az általunk létrehozott osztályok az <code>object</code>-ből származnak, az objektumaink is rendelkeznek <code>ToString</code> és <code>Equals</code> metódusokkal.</p><p>Tegyük fel, hogy van egy egyszerű <code>Point</code> osztályunk, amelyet így definiálunk:</p><div class="language-csharp line-numbers-mode" data-ext="cs"><pre class="language-csharp"><code><span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">Point</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token return-type class-name"><span class="token keyword">float</span></span> X <span class="token punctuation">{</span> <span class="token keyword">get</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
    <span class="token keyword">public</span> <span class="token return-type class-name"><span class="token keyword">float</span></span> Y <span class="token punctuation">{</span> <span class="token keyword">get</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
    <span class="token keyword">public</span> <span class="token function">Point</span><span class="token punctuation">(</span><span class="token class-name"><span class="token keyword">float</span></span> x<span class="token punctuation">,</span> <span class="token class-name"><span class="token keyword">float</span></span> y<span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        X <span class="token operator">=</span> x<span class="token punctuation">;</span> 
        Y <span class="token operator">=</span> y<span class="token punctuation">;</span>
    <span class="token punctuation">}</span> 
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Bár ez az osztály nem definiálja a <code>ToString</code> vagy <code>Equals</code> metódusokat, mégis rendelkezik velük:</p><div class="language-csharp line-numbers-mode" data-ext="cs"><pre class="language-csharp"><code><span class="token class-name">Point</span> p1 <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token constructor-invocation class-name">Point</span><span class="token punctuation">(</span><span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">4</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
<span class="token class-name">Point</span> p2 <span class="token operator">=</span> p1<span class="token punctuation">;</span>
Console<span class="token punctuation">.</span><span class="token function">WriteLine</span><span class="token punctuation">(</span>p1<span class="token punctuation">.</span><span class="token function">ToString</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> 
Console<span class="token punctuation">.</span><span class="token function">Write</span><span class="token punctuation">(</span>p1<span class="token punctuation">.</span><span class="token function">Equals</span><span class="token punctuation">(</span>p2<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Ez azért van, mert a <code>Point</code> ezeket a metódusokat az alaposztályából, az <code>object</code>-ből örökli.</p><p>Fontos, hogy mivel a származtatott osztály rendelkezik az alaposztály összes képességével, használhatjuk azokat bárhol. Egy egyszerű példa erre:</p><div class="language-csharp line-numbers-mode" data-ext="cs"><pre class="language-csharp"><code><span class="token class-name"><span class="token keyword">object</span></span> thing <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token constructor-invocation class-name">Point</span><span class="token punctuation">(</span><span class="token number">2</span><span class="token punctuation">,</span> <span class="token number">4</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p>A változó egy objektum típusú valamire való hivatkozást tartalmaz. Egy <code>Point</code> példányra való hivatkozást adunk meg. A Point egy másik osztály, mint az <code>object</code>, de a <code>Point</code> az <code>object</code>-ből származik és így egyként kezelhető.</p><p>Ez érdekessé teszi a dolgokat. A <code>thing</code> változó tudja, hogy objektumokat tartalmaz. Használhatja a <code>ToString</code> és az <code>Equals</code> metódusát. De a változó nem ígéri, hogy valami objektumnál konkrétabb dologra való hivatkozással rendelkezik:</p><div class="language-csharp line-numbers-mode" data-ext="cs"><pre class="language-csharp"><code>Console<span class="token punctuation">.</span><span class="token function">WriteLine</span><span class="token punctuation">(</span>thing<span class="token punctuation">.</span><span class="token function">ToString</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// Safe. </span>
Console<span class="token punctuation">.</span><span class="token function">WriteLine</span><span class="token punctuation">(</span>thing<span class="token punctuation">.</span>X<span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// Compiler error.</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>Annak ellenére, hogy a <code>Point</code> egy példányát helyeztük a <code>thing</code> változóba, maga a változó csak azt tudja garantálni, hogy egy objektumra való hivatkozással rendelkezik. Lehet, hogy ez egy <code>Point</code>, de a változó és a fordító ezt nem tudja garantálni, még akkor sem, ha az ember a kódot vizsgálva ezt látja. Ha egyszer egy származtatott osztályra, például <code>Point</code>-ra való hivatkozást helyezünk egy alaposztálybeli változóba, például <code>object</code>-be, ez az információ nem vész el örökre. Később látni fogjuk, hogyan vizsgálhatjuk meg egy objektum típusát és szükség esetén a származtatott típusra kasztolhatjuk, hogy visszanyerjük a hozzáférést az objektumhoz, mint származtatott típushoz.</p><h2 id="alaposztaly-kivalasztasa" tabindex="-1"><a class="header-anchor" href="#alaposztaly-kivalasztasa" aria-hidden="true">#</a> Alaposztály kiválasztása</h2><p>Alapértelmezés szerint minden osztály az <code>object</code>-től örököl, de nem nehéz egy másik osztályt alaposztályként használni.</p><div class="hint-container danger"><p class="hint-container-title">Ez a kód részlet csupán az öröklődés illusztrációját szolgálja.</p></div><p>Korábbi már beszéltünk azokról az osztályokról, amelyeket egy <strong>Aszteroida játékhoz</strong> definiálhatnánk. Még készítettünk is egy <strong>Aszteroida osztályt</strong>, amely magában foglalta a térben való sodródás logikáját. Említettük, hogy a játékos hajójának és a lövedékeknek ugyanaz a viselkedése kell, hogy legyen. Egy olyan <code>GameObject</code> osztályt hozhatnánk létre, amely alapul szolgálhatna ennek:</p><div class="language-csharp line-numbers-mode" data-ext="cs"><pre class="language-csharp"><code><span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">GameObject</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token return-type class-name"><span class="token keyword">float</span></span> PositionX <span class="token punctuation">{</span> <span class="token keyword">get</span><span class="token punctuation">;</span> <span class="token keyword">set</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
    <span class="token keyword">public</span> <span class="token return-type class-name"><span class="token keyword">float</span></span> PositionY <span class="token punctuation">{</span> <span class="token keyword">get</span><span class="token punctuation">;</span> <span class="token keyword">set</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
    <span class="token keyword">public</span> <span class="token return-type class-name"><span class="token keyword">float</span></span> VelocityX <span class="token punctuation">{</span> <span class="token keyword">get</span><span class="token punctuation">;</span> <span class="token keyword">set</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
    <span class="token keyword">public</span> <span class="token return-type class-name"><span class="token keyword">float</span></span> VelocityY <span class="token punctuation">{</span> <span class="token keyword">get</span><span class="token punctuation">;</span> <span class="token keyword">set</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>

    <span class="token keyword">public</span> <span class="token return-type class-name"><span class="token keyword">void</span></span> <span class="token function">Update</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        PositionX <span class="token operator">+=</span> VelocityX<span class="token punctuation">;</span>
        PositionY <span class="token operator">+=</span> VelocityY<span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Most létrehozhatunk egy <code>Asteroid</code> osztályt, amely csak az aszteroidára jellemző dolgokat tartalmaz és jelzi, hogy ez az osztály a <code>GameObject</code>-ből származik (<em>a sima objektum helyett</em>):</p><div class="language-csharp line-numbers-mode" data-ext="cs"><pre class="language-csharp"><code><span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">Asteroid</span> <span class="token punctuation">:</span> <span class="token type-list"><span class="token class-name">GameObject</span></span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token return-type class-name"><span class="token keyword">float</span></span> Size <span class="token punctuation">{</span> <span class="token keyword">get</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
    <span class="token keyword">public</span> <span class="token return-type class-name"><span class="token keyword">float</span></span> RotationAngle <span class="token punctuation">{</span> <span class="token keyword">get</span><span class="token punctuation">;</span> <span class="token punctuation">}</span> 
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Ahogy látható a <code>GameObject</code> osztály az alaposztályt (<em>ősosztályát</em>) úgy azonosítja, hogy a nevét kettőspont után helyezi. Az <strong>Asteroid</strong> örökli a <code>PositionX</code>, <code>PositionY</code>, <code>VelocityX</code>, <code>VelocityY</code> és <code>Update</code> tulajdonságokat az alaposztályától, a <code>GameObject</code>-től. Ezenkívül új <code>Size</code> és <code>RotationAngle</code> tulajdonságokat is hozzáad, amelyek egyedülállóak az <strong>Asteroid</strong> számára.</p><p>Tegyük fel, hogy készítünk <code>Bullet</code> és <code>Ship</code> osztályokat is, amelyek szintén a <code>GameObject</code>-ből származtathatók. Felállíthatnánk egy új <code>Asteroids</code> játékot egy vegyes típusú játékobjektumok gyűjteményével, így:</p><div class="language-csharp line-numbers-mode" data-ext="cs"><pre class="language-csharp"><code><span class="token class-name">GameObject<span class="token punctuation">[</span><span class="token punctuation">]</span></span> gameObjects <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token constructor-invocation class-name">GameObject<span class="token punctuation">[</span><span class="token punctuation">]</span></span>
<span class="token punctuation">{</span>
    <span class="token keyword">new</span> <span class="token constructor-invocation class-name">Asteroid</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token keyword">new</span> <span class="token constructor-invocation class-name">Asteroid</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token keyword">new</span> <span class="token constructor-invocation class-name">Asteroid</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span>
    <span class="token keyword">new</span> <span class="token constructor-invocation class-name">Bullet</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token keyword">new</span> <span class="token constructor-invocation class-name">Ship</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
<span class="token punctuation">}</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container note"><p class="hint-container-title">Oké, valószínűleg nem úgy kezdenéd a játékot, hogy egy golyó már repül körülötted de érted a lényeget.</p></div><p>A tömb <code>GameObject</code> példányokra mutató hivatkozásokat tárol. De ebben a tömbben <code>Asteroid</code>, <code>Bullet</code> és <code>Ship</code> osztályok példányai találhatók. A tömbnek ezzel nincs problémája, mert mindhárom típus a <code>GameObject</code>-ből származik.</p><p>Itt válik érdekessé a dolog:</p><div class="language-csharp line-numbers-mode" data-ext="cs"><pre class="language-csharp"><code><span class="token keyword">foreach</span> <span class="token punctuation">(</span><span class="token class-name">GameObject</span> item <span class="token keyword">in</span> gameObjects<span class="token punctuation">)</span>
    item<span class="token punctuation">.</span><span class="token function">Update</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>Annak ellenére, hogy összesen négy osztállyal van dolgunk (<strong>egy alaposztály és három származtatott osztály</strong>), bármelyikükön meghívhatjuk az <code>Update</code> metódust, mivel azt a <code>GameObject</code> definiálja. A származtatott osztályok mindegyike garantáltan rendelkezik ezzel a metódussal.</p><p>Az öröklődés csak egy irányban működik. Bár egy <code>Asteroid</code>-ot használhatsz, ha egy <code>GameObject</code>-re van szükség, de nem használhatsz egy <code>GameObject</code>-et ott, ahol egy <code>Asteroid</code>-ra van szükség. Ugyanígy nem használhatsz egy <code>Asteroid</code>-ot ott, ahol egy <code>Ship</code> vagy <code>Bullet</code> szükséges:</p><div class="language-csharp line-numbers-mode" data-ext="cs"><pre class="language-csharp"><code><span class="token class-name">Asteroid</span> asteroid <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token constructor-invocation class-name">GameObject</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span> <span class="token comment">// COMPILER ERROR!</span>
<span class="token class-name">Ship</span> ship <span class="token operator">=</span> <span class="token keyword">new</span> <span class="token constructor-invocation class-name">Asteroid</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span>           <span class="token comment">// COMPILER ERROR!</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>Az örökléssel kapcsolatban álló osztályok gyűjteményét - (<em>mint például ezt a négyet</em>) - öröklési hierarchiának nevezzük.</p><p>Az öröklési hierarchiák olyan mélyek lehetnek, amilyen mélyre csak szükségünk van rájuk. Például:</p><div class="language-csharp line-numbers-mode" data-ext="cs"><pre class="language-csharp"><code><span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">Scout</span> <span class="token punctuation">:</span> <span class="token type-list"><span class="token class-name">Ship</span></span> <span class="token punctuation">{</span> <span class="token comment">/* ... */</span> <span class="token punctuation">}</span>
<span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">Bomber</span> <span class="token punctuation">:</span> <span class="token type-list"><span class="token class-name">Ship</span></span> <span class="token punctuation">{</span> <span class="token comment">/* ... */</span> <span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>A <code>Bomber</code> és <code>Scout</code> osztályok a <code>Ship</code> osztályból származnak, amely a <code>GameObject</code> osztályból származik, amely pedig az <code>object</code> osztályból származik. Egy <code>Bomber</code>-t bárhol használhatsz, ahol egy <code>Ship</code>, <code>GameObject</code> vagy <code>object</code> szükséges.</p><p><strong>Azonban az osztályok csak egyetlen alaposztályt választhatnak.</strong> Nem származtathatsz közvetlenül több osztályból. Vannak helyzetek, amikor ez némileg korlátozó, de ebből bonyodalmak adódnak, ezért a <strong>C# nyelv tiltja az egynél több alaposztályból való öröklést</strong>.</p><h2 id="konstruktorok" tabindex="-1"><a class="header-anchor" href="#konstruktorok" aria-hidden="true">#</a> Konstruktorok</h2><p>A származtatott osztály a legtöbb tagot az alaposztályból örökli, de a konstruktorokat nem. A konstruktorok egy új objektumot egy érvényes kiindulási állapotba helyeznek. Az alaposztály konstruktora nem tud garanciát vállalni egy származtatott osztály objektumának érvényességére. A konstruktorok tehát nem öröklődnek és a származtatott osztályoknak saját konstruktorokat kell biztosítaniuk. Azonban az alaposztályban definiált konstruktorokat használhatjuk - <strong>és kell is használnunk</strong> -, amikor új konstruktorokat készítünk a származtatott osztályban.</p><p>Ha az alaposztályban létezik paraméter nélküli konstruktor, akkor a származtatott osztály konstruktora automatikusan meg fogja hívni azt, mielőtt a saját kódját futtatná.</p><div class="hint-container info"><p class="hint-container-title">Ne feledjük...</p><p>Ha egy osztály nem definiál konstruktort, a fordító egy egyszerű, paraméter nélküli konstruktort fog generálni.</p></div><p>A fordító által készített konstruktor itt a mi céljainknak tökéletesen megfelel. Ez történt a mi egyszerű öröklési hierarchiánkban. Sem a <code>GameObject</code>, sem az <code>Asteroid</code> nem definiált külön konstruktort. A fordító mindkét osztályban generált egy alapértelmezett paraméter nélküli konstruktort és az <code>Asteroid</code>-ban lévő automatikusan hívta a <code>GameObject</code>-ben lévőt.</p><p>Ugyanez történik, ha manuálisan paraméter nélküli konstruktorokat készítünk:</p><div class="language-csharp line-numbers-mode" data-ext="cs"><pre class="language-csharp"><code><span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">GameObject</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token function">GameObject</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        PositionX <span class="token operator">=</span> <span class="token number">2</span><span class="token punctuation">;</span> PositionY <span class="token operator">=</span> <span class="token number">4</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
    <span class="token comment">// ...</span>
<span class="token punctuation">}</span>
<span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">Asteroid</span> <span class="token punctuation">:</span> <span class="token type-list"><span class="token class-name">GameObject</span></span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token function">Asteroid</span><span class="token punctuation">(</span><span class="token punctuation">)</span>
    <span class="token punctuation">{</span>
        RotationAngle <span class="token operator">=</span> <span class="token operator">-</span><span class="token number">1</span><span class="token punctuation">;</span>
    <span class="token punctuation">}</span>
    <span class="token comment">// ...</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Itt az <code>Asteroid</code> paraméter nélküli konstruktora automatikusan meghívja a <code>GameObject</code> paraméter nélküli konstruktorát. A <code>new Asteroid()</code> hívása belép az <code>Asteroid</code> konstruktorába és azonnal a <code>GameObject</code> paraméter nélküli konstruktorába ugrik a <code>PositionX</code> és <code>PositionY</code> beállításához, majd visszatér az <code>Asteroid</code> konstruktorába a <code>RotationAngle</code> beállításához.</p><p>Tegyük fel, hogy egy alaposztály egynél több konstruktorral rendelkezik, vagy nem tartalmaz paraméter nélküli konstruktort (<em>mindkettő gyakori eset</em>). Ebben az esetben kifejezetten meg kell adnunk, hogy a származtatott osztályban lévő új konstruktorok melyik alaposztály konstruktorára épüljenek.</p><p>Tegyük fel, hogy a <code>GameObjectnek</code> csak ez a konstruktora van:</p><div class="language-csharp line-numbers-mode" data-ext="cs"><pre class="language-csharp"><code><span class="token keyword">public</span> <span class="token function">GameObject</span><span class="token punctuation">(</span><span class="token class-name"><span class="token keyword">float</span></span> positionX<span class="token punctuation">,</span> <span class="token class-name"><span class="token keyword">float</span></span> positionY<span class="token punctuation">,</span> <span class="token class-name"><span class="token keyword">float</span></span> velocityX<span class="token punctuation">,</span> <span class="token class-name"><span class="token keyword">float</span></span> velocityY<span class="token punctuation">)</span>
<span class="token punctuation">{</span>
    PositionX <span class="token operator">=</span> positionX<span class="token punctuation">;</span> PositionY <span class="token operator">=</span> positionY<span class="token punctuation">;</span>
    VelocityX <span class="token operator">=</span> velocityX<span class="token punctuation">;</span> VelocityY <span class="token operator">=</span> velocityY<span class="token punctuation">;</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Mivel nincs meghívható paraméter nélküli konstruktor, az <code>Asteroid</code>-ban definiált bármely konstruktornak külön jeleznünk kell, hogy ezt a másik konstruktort használja és argumentumokat kell megadnunk a paramétereihez:</p><div class="language-csharp line-numbers-mode" data-ext="cs"><pre class="language-csharp"><code><span class="token keyword">public</span> <span class="token function">Asteroid</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">:</span> <span class="token keyword">base</span><span class="token punctuation">(</span><span class="token number">0</span><span class="token punctuation">,</span><span class="token number">0</span><span class="token punctuation">,</span><span class="token number">0</span><span class="token punctuation">)</span>
<span class="token punctuation">{</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Viszonylag gyakori, hogy az aktuális konstruktorból paramétereket adunk át az alaposztály konstruktorának, így a következő lehet gyakoribb:</p><div class="language-csharp line-numbers-mode" data-ext="cs"><pre class="language-csharp"><code><span class="token keyword">public</span> <span class="token function">Asteroid</span><span class="token punctuation">(</span><span class="token class-name"><span class="token keyword">float</span></span> positionX<span class="token punctuation">,</span> <span class="token class-name"><span class="token keyword">float</span></span> positionY<span class="token punctuation">,</span> <span class="token class-name"><span class="token keyword">float</span></span> velocityX<span class="token punctuation">,</span> <span class="token class-name"><span class="token keyword">float</span></span> velocityY<span class="token punctuation">)</span>
                                 <span class="token punctuation">:</span> <span class="token keyword">base</span><span class="token punctuation">(</span>positionX<span class="token punctuation">,</span> positionY<span class="token punctuation">,</span> velocityX<span class="token punctuation">,</span> velocityY<span class="token punctuation">)</span>
<span class="token punctuation">{</span> 
<span class="token punctuation">}</span>
</code></pre><div class="highlight-lines"><br><div class="highlight-line"> </div><br><br></div><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><div class="hint-container tip"><p class="hint-container-title">Hasonlót láttunk már...</p><p>Csak ott a <code>base</code> helyett a <code>this</code> kulcsszóval. Ez ugyanígy működik, csak a <code>this</code> az osztály konstruktorai helyett a <code>base</code> az osztály konstruktoraihoz nyúl le. A <code>this</code> és a <code>base</code> nem használható együtt egy konstruktorban.</p></div><p>Ezek a szabályok kicsit bonyolultak, ezért vessünk egy pillantást rájuk. Az osztálykonstruktorok nem öröklődnek úgy, mint más tagok. A leszármazott osztályban lévő konstruktornak hivatkoznia kell egy konstruktorra az alap osztályban (<em>a <code>base</code> kulcsszóval</em>), hogy arra építhessen. Vagy másik konstruktort hívhat meg ugyanabban az osztályban (<em>a <code>this</code> kulcsszóval</em>). Ha létezik paraméter nélküli konstruktor, beleértve azt is, amit a fordító generál, nem szükséges kifejezetten megadni <code>base</code> kulcsszóval. <em>De ne aggódjunk a fordító segíteni fog az esetleges problémák azonosításában.</em></p><h2 id="a-protected-lathatosag" tabindex="-1"><a class="header-anchor" href="#a-protected-lathatosag" aria-hidden="true">#</a> A <code>protected</code> láthatóság</h2><p>Három láthatósági módosítóval találkoztunk már: <code>private</code>, <code>public</code> és <code>internal</code>. A negyedik hozzáférhetőségi módosító a <code>protected</code> kulcsszó. Ha valami <code>protected</code>, akkor az osztályon belül és a származtatott osztályokon belül is elérhető. Például:</p><div class="language-csharp line-numbers-mode" data-ext="cs"><pre class="language-csharp"><code><span class="token keyword">public</span> <span class="token keyword">class</span> <span class="token class-name">GameObject</span>
<span class="token punctuation">{</span>
    <span class="token keyword">public</span> <span class="token return-type class-name"><span class="token keyword">float</span></span> PositionX <span class="token punctuation">{</span> <span class="token keyword">get</span><span class="token punctuation">;</span> <span class="token keyword">protected</span> <span class="token keyword">set</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
    <span class="token keyword">public</span> <span class="token return-type class-name"><span class="token keyword">float</span></span> PositionY <span class="token punctuation">{</span> <span class="token keyword">get</span><span class="token punctuation">;</span> <span class="token keyword">protected</span> <span class="token keyword">set</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
    <span class="token keyword">public</span> <span class="token return-type class-name"><span class="token keyword">float</span></span> VelocityX <span class="token punctuation">{</span> <span class="token keyword">get</span><span class="token punctuation">;</span> <span class="token keyword">protected</span> <span class="token keyword">set</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
    <span class="token keyword">public</span> <span class="token return-type class-name"><span class="token keyword">float</span></span> VelocityY <span class="token punctuation">{</span> <span class="token keyword">get</span><span class="token punctuation">;</span> <span class="token keyword">protected</span> <span class="token keyword">set</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Ha ezeket a beállítókat <code>public</code> helyett <code>protected</code> tesszük, akkor csak a <code>GameObject</code> és a származtatott osztályai (<em>például az <code>Asteroid</code> és a <code>Ship</code></em>) módosíthatják ezeket a tulajdonságokat, a kívülről viszont nem.</p><h2 id="sealed-osztaly" tabindex="-1"><a class="header-anchor" href="#sealed-osztaly" aria-hidden="true">#</a> <code>sealed</code> osztály</h2><p>Ha meg akarjuk tiltani másoknak, hogy egy adott osztályból származtassanak, megakadályozhatjuk ezt a <code>sealed</code> módosító hozzáadásával az osztály definíciójához:</p><div class="language-csharp line-numbers-mode" data-ext="cs"><pre class="language-csharp"><code><span class="token keyword">public</span> <span class="token keyword">sealed</span> <span class="token keyword">class</span> <span class="token class-name">Asteroid</span> <span class="token punctuation">:</span> <span class="token type-list"><span class="token class-name">GameObject</span></span>
<span class="token punctuation">{</span>
<span class="token comment">// ...</span>
<span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>Ebben az esetben senki sem lesz képes új osztályt származtatni az <code>Asteroid</code> alapján. Ritka, hogy egy osztályból való származtatás teljes tiltását akarjuk, de alkalmanként ez is előfordulhat. Egy osztály lezárása néha teljesítménynövekedést is eredményezhet.</p>`,82),l=[o];function p(c,i){return a(),n("div",null,l)}const d=s(t,[["render",p],["__file","lesson1.html.vue"]]);export{d as default};
